  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'atlas_bot') THEN
    CREATE ROLE atlas_bot LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION;
  END IF;
END $$;
